  assert.equal((await state()).style,entry.sentences[i].narration?'italic':'normal');assert.equal((await state()).tag,entry.sentences[i].narration?'EM':'SPAN');checked++;
  if((await state()).text!==entry.sentences[i].text)await page.locator('.dialogue-layer .text').click();assert.equal((await state()).text,entry.sentences[i].text);
