  if(i<entry.sentences.length-1)await page.locator('.dialogue-layer .text').click();
 }}
 await page.evaluate(()=>{v.updateTextImageSequence([{text:'Wayne : Tu cherches ta sœur Lucie ?',imageName:'wayne-eyepatch-v1.png',typewriterMs:0}],'dia1');v.endSentences='dia1';});assert.equal((await state()).style,'normal');assert.deepEqual(errors,[]);
 passed=true;const result={realSocketEntry:true,narratorItalic:true,spokenTextNormal:true,sentencesChecked:checked,narrationCount:entries.flatMap(e=>e.sentences).filter(s=>s.narration).length,typingAndActionPreserved:true,stableTypewriterHeight:true,otherDialogueNormal:true,viewports:4,screens,errors};fs.writeFileSync(out+'/results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{if(!passed&&page)await page.screenshot({path:out+'/failure.png'}).catch(()=>{});await browser?.close();await new Promise(r=>io.close(r));await new Promise(r=>setTimeout(r,200));if(userId)await db.execute('DELETE FROM users WHERE id=?',[userId]);await db.end();}})().catch(e=>{console.error(e.stack);process.exitCode=1});
